import os


class Config:
    """
    Global configuration for the Physically-Consistent Stabilized Dense-Hybrid Network (PCSDH-Net).
    """

    # ==========================================
    # File Paths
    # ==========================================
    # Metadata paths (generated by the metadata script)
    TRAIN_PATH = "./metadata/train.csv"
    VAL_PATH = "./metadata/validation.csv"
    TEST_PATH = "./metadata/test.csv"

    # Input paths
    SAMPLE_SUBMISSION_PATH = "./input/sample_submission.csv"

    # Working directory for caching and model checkpoints
    WORKING_DIR = "./working/idea_18/"
    OUTPUT_PATH = "./submission/submission.csv"

    # ==========================================
    # Reproducibility
    # ==========================================
    SEED = 42

    # ==========================================
    # Training Hyperparameters
    # ==========================================
    # Small batch size for better generalization (Ref: solution_lesson_node_00018)
    BATCH_SIZE = 128

    # Sufficient budget for hybrid branch synchronization (Ref: solution_lesson_node_00039)
    EPOCHS = 80

    # Standard learning rate
    LEARNING_RATE = 1e-3

    # Mandatory gradient clipping for stability in hybrid architectures (Ref: solution_lesson_node_00065)
    GRAD_CLIP = 1.0

    # ==========================================
    # Model Architecture (PCSDH-Net)
    # ==========================================
    # Branch 1: Stabilized Deep Dense Large-Kernel TCN
    CNN_KERNEL_SIZE = 9
    CNN_DILATION = 1  # Dense convolution for local fidelity
    CNN_FILTERS = [64, 128, 256, 512]  # Scaling channel capacity
    CNN_DROPOUT = 0.1  # Stability innovation

    # Branch 2: High-Capacity Bidirectional LSTM
    LSTM_HIDDEN_SIZE = 512
    LSTM_LAYERS = 3
    LSTM_BIDIRECTIONAL = True

    # Fusion
    FC_DROPOUT = 0.1

    # ==========================================
    # Feature Engineering
    # ==========================================
    # List of column names to be used as input features.
    # These must be generated by the preprocessing pipeline.
    FEATURE_COLS = [
        "time_step",  # Temporal Context
        "u_in",  # Control Input
        "u_out",  # Control Input (Binary)
        "R",  # Lung Attribute
        "C",  # Lung Attribute
        "dt",  # Time-Delta (Crucial for variable-rate physics)
        "u_in_diff",  # Acceleration (Derivative)
        "area",  # Volume (Integral of u_in * dt)
        "R_u_in",  # Interaction: Resistive Pressure component
        "area_C",  # Interaction: Elastic Pressure component
        "u_in_next1",  # Lookahead t+1
        "u_in_next2",  # Lookahead t+2
        "u_in_next3",  # Lookahead t+3
        "u_in_next4",  # Lookahead t+4
    ]

    @staticmethod
    def setup_dirs():
        """
        Ensures the working directory exists.
        """
        os.makedirs(Config.WORKING_DIR, exist_ok=True)
        os.makedirs(os.path.dirname(Config.OUTPUT_PATH), exist_ok=True)
